+	dev_info(core->dev, "Remove ISP Core\n");
+
+	for (unsigned int i = 0; i < RISP_CORE_NUM_PADS; i++)
+		risp_core_io_destroy(&core->io[i]);
+
+	v4l2_device_unregister_subdev(&core->subdev);
+
+	mutex_destroy(&core->io_lock);
+	rppx1_destroy(core->rpp);
+}
